class RequireRole:
    def __init__(self, roles: List[str]):
        self.roles = roles

    def __call__(self, user: User = Depends(get_current_user)) -> User:
        if user.role not in self.roles:
            raise HTTPException(status_code=403, detail="Insufficient role privileges")
        return user

@router.put("/departments/{dept_id}/budget-cap")
def update_department_budget(
    dept_id: int,
    cap_data: BudgetCapUpdate,
    user: User = Depends(RequireRole(["dept_manager", "finance_director"])),
    db: Session = Depends(get_db)
):
    dept = db.query(Department).filter(Department.id == dept_id).first()
    if not dept:
        raise HTTPException(status_code=404, detail="Department not found")

    if user.role == "dept_manager" and dept.manager_id != user.id:
        raise HTTPException(status_code=403, detail="Cannot alter budget cap of another department")

    dept.annual_budget_cap = cap_data.annual_budget_cap
    db.commit()
    return {"status": "budget cap updated", "department_id": dept_id}
